// One row per service you want to synthetically monitor.
// Point 'url' at each service's own health endpoint (Spring Boot Actuator, etc.)
const endpoints = [
  { service_id: 101, service_name: 'auth-service', endpoint: '/posts/999999', http_method: 'GET', url: 'https://jsonplaceholder.typicode.com/posts/999999' },
  ];
return endpoints.map(e => ({ json: e }));

const startMs = $('Start Timer').item.json.start_ms;
const responseTimeMs = Date.now() - startMs;
const statusCode = $json.statusCode ?? 0;
const isHealthy = statusCode >= 200 && statusCode < 400;
const meta = $('Endpoints List').item.json;

return [{
  json: {
    ...meta,
    status_code: statusCode,
    response_time_ms: responseTimeMs,
    is_healthy: isHealthy,
    checked_at: new Date().toISOString(),
    response_body: JSON.stringify($json.body || {}).slice(0, 500)
  }
}];

const d = $json;

// Generate UUID if not provided
const requestId =
  d.request_id ||
  (typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).substring(2, 15)}`);

// Parse JSON safely
const safeParse = (value) => {
  if (!value) return {};
  if (typeof value === "object") return value;

  try {
    return JSON.parse(value);
  } catch (e) {
    return { raw: value };
  }
};

// Determine severity
const getSeverity = (statusCode) => {
  if (statusCode >= 500 || statusCode === 0) return "CRITICAL";
  if (statusCode >= 400) return "HIGH";
  if (statusCode >= 300) return "MEDIUM";
  return "LOW";
};

// Extract stack trace if available
const stackTrace =
  d.response?.stack_trace ||
  d.stack_trace ||
  d.error?.stack ||
  null;

// Exception type
const exceptionType =
  d.exception_type ||
  d.error?.name ||
  d.exception ||
  "UnknownException";

// Error message
const errorMessage =
  d.error_message ||
  d.error?.message ||
  `Health check failed with status ${d.status_code}`;

// AI Root Cause
const aiRootCause =
  d.ai_root_cause ||
  (
    d.status_code >= 500
      ? "Server-side error encountered while processing the request."
      : d.status_code >= 400
      ? "Client request validation or authorization failure."
      : d.status_code === 0
      ? "Unable to connect to the endpoint. Possible network or DNS issue."
      : "Unknown failure."
  );

// AI Fix Recommendation
const aiFixRecommendation =
  d.ai_fix_recommendation ||
  (
    d.status_code >= 500
      ? "Implement retries with exponential backoff, review server logs, and verify downstream dependencies."
      : d.status_code >= 400
      ? "Validate request payload, headers, authentication credentials, and API contract."
      : d.status_code === 0
      ? "Verify endpoint availability, firewall rules, DNS resolution, and network connectivity."
      : "Review logs and monitoring data for additional diagnostics."
  );

// AI Code Example
const aiCodeExample =
`try {
    const response = await axios({
        method: "${d.http_method || "GET"}",
        url: "${d.endpoint || ""}"
    });
} catch (err) {
    console.error(err.response?.status);
    console.error(err.response?.data);
}`;

return [{
  json: {

    // Service Details
    service_id: d.service_id,
    service_name: d.service_name,

    // API Details
    endpoint: d.endpoint,
    method: d.http_method || d.method,
    http_method: d.http_method || d.method,

    // Response
    status_code: d.status_code,
    response_time_ms: d.response_time_ms,

    // Failure Details
    severity: getSeverity(d.status_code),
    category: "SYNTHETIC_MONITORING",
    exception_type: exceptionType,
    error_message: errorMessage,
    stack_trace: stackTrace,

    // Request
    request_id: requestId,
    request_body: safeParse(d.request_body),
    request_payload: safeParse(d.request_body),

    // Response
    response_body: safeParse(d.response_body),
    response_payload: safeParse(d.response_body),

    // Metadata
    created_at: d.checked_at || new Date().toISOString(),

    // AI Analysis
    ai_code_example: aiCodeExample,
    ai_root_cause: aiRootCause,
    ai_fix_recommendation: aiFixRecommendation,

    // Optional Additional Fields
    host: d.host || null,
    environment: d.environment || null,
    trace_id: d.trace_id || null,
    correlation_id: d.correlation_id || null,
    execution_id: d.execution_id || null,
    monitor_name: d.monitor_name || null,
    monitor_type: d.monitor_type || "HEALTH_CHECK",

    // Preserve original payload
    raw_event: d
  }
}];
